/**
 * @method
 * @name scwin.tx_fn_Modify
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_Modify = async function () {
    const sbmOptions = {
        id: "tx_fn_Modify",
        method: "post",
        action: "/list/listNotify.do",
        ref: "dma_ModifyReq",
        target: "dlt_notiDetailListNotifyDataAttachVO=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil05401.tx_fn_Modify" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

